#![allow(dead_code)]
mod model;
mod baseline;
mod candidate;
use model::*;
use std::collections::BTreeSet;

fn inst(name: &str, op: Op) -> Inst {
    Inst::new((!name.is_empty()).then(|| name.into()), op)
}
fn arg(value: Val) -> Arg { Arg::new(Ty::Int(32), value) }
fn local(name: &str) -> Val { Val::Local(name.into()) }
fn block(name: &str, instructions: Vec<Inst>) -> Block { Block { name: name.into(), instructions } }
fn module(blocks: Vec<Block>, params: Vec<Param>) -> Module {
    Module { triple: "x86_64-unknown-linux-gnu".into(), fingerprint: "independent-CP06-review".into(), items: vec![Item::Function(Function { name: "reviewed".into(), linkage: Linkage::External, signature: Signature::new(Ty::Int(32),params), attrs: vec![], blocks:Some(blocks) })] }
}
fn chain() -> Module {
    let mut blocks=vec![block("entry",vec![inst("seed",Op::Freeze(arg(local("input")))),inst("",Op::Branch("b1".into()))])];
    for i in 1..=4 {
        let dep=if i==1 {"seed".to_owned()} else {format!("v{}",i-1)};
        let term=if i==4 {Op::Return(Some(arg(local("v4"))))} else {Op::Branch(format!("b{}",i+1))};
        blocks.push(block(&format!("b{i}"),vec![inst(&format!("v{i}"),Op::Freeze(arg(local(&dep)))),inst("",term)]));
    }
    module(blocks,vec![Param::new(Ty::Int(32),"input")])
}
fn diamond() -> Module {
    module(vec![
      block("entry",vec![inst("",Op::CondBranch{condition:local("choose"),yes:"a".into(),no:"b".into()})]),
      block("a",vec![inst("left",Op::Freeze(arg(Val::Int(41)))),inst("",Op::Branch("join".into()))]),
      block("b",vec![inst("right",Op::Freeze(arg(Val::Int(43)))),inst("",Op::Branch("join".into()))]),
      block("join",vec![inst("merged",Op::Phi{ty:Ty::Int(32),incoming:vec![(local("left"),"a".into()),(local("right"),"b".into())]}),inst("",Op::Branch("after".into()))]),
      block("after",vec![inst("",Op::Return(Some(arg(local("merged")))))]),
    ],vec![Param::new(Ty::Int(1),"choose")])
}
fn blocks(m:&mut Module)->&mut Vec<Block> { let Item::Function(f)=&mut m.items[0] else{panic!()};f.blocks.as_mut().unwrap() }
fn perms(values:&mut [usize],offset:usize, out:&mut Vec<Vec<usize>>) {
    if offset==values.len(){out.push(values.to_vec());return}
    for i in offset..values.len(){values.swap(i,offset);perms(values,offset+1,out);values.swap(i,offset)}
}
fn audit(m:&Module, count:&mut [usize;3]) {
    let before=m.to_text();let old=baseline::validate(m);let new=candidate::validate(m);count[0]+=1;
    assert_eq!(old.is_ok(),new.is_ok(),"acceptance mismatch: {before}");
    match (old,new) {
      (Err(a),Err(b))=>{count[2]+=1;assert_eq!(a,b,"diagnostic mismatch");},
      (Ok(_),Ok(schedule))=>{
        count[1]+=1;
        for item in &m.items { let Item::Function(f)=item else {continue};let Some(body)=&f.blocks else {continue};
          let positions=&schedule.functions[&f.name];let expected=body.iter().enumerate().flat_map(|(b,block)|block.instructions.iter().enumerate().filter_map(move |(i,v)|(!matches!(v.op,Op::Phi{..})).then_some((b,i)))).collect::<BTreeSet<_>>();
          assert_eq!(positions.iter().copied().collect::<BTreeSet<_>>(),expected);assert_eq!(positions.len(),expected.len());
          let mut available=f.signature.params.iter().map(|p|p.name.as_ref().unwrap().clone()).collect::<BTreeSet<_>>();
          for b in body {for i in &b.instructions{if matches!(i.op,Op::Phi{..}){available.insert(i.result.as_ref().unwrap().clone());}}}
          let mut last=vec![None;body.len()];
          for &(b,i) in positions {
            if let Some(old)=last[b]{assert!(old<i,"block effect order changed");}last[b]=Some(i);
            let instruction=&body[b].instructions[i];
            for value in instruction.op.values(){let mut uses=vec![];value.local_uses(&mut uses);for name in uses{assert!(available.contains(name),"handle not available: {name}");}}
            if let Some(name)=&instruction.result{available.insert(name.clone());}
          }
        }
      },_=>unreachable!()
    }
    assert_eq!(m.to_text(),before,"model changed during preflight");
}
fn main(){
    let mut count=[0;3];let mut orders=vec![];perms(&mut [1,2,3,4],0,&mut orders);
    for mut original in [chain(),diamond()] {
      let source=blocks(&mut original).clone();
      for order in &orders {
        let mut m=original.clone();*blocks(&mut m)=std::iter::once(source[0].clone()).chain(order.iter().map(|&i|source[i].clone())).collect();audit(&m,&mut count);
        for b in 1..5 {
          for dependency in ["seed","v1","v2","v3","v4","input","absent","merged","left","right"] {
            let mut changed=m.clone();
            if let Op::Freeze(arg)=&mut blocks(&mut changed)[b].instructions[0].op {arg.value=local(dependency);audit(&changed,&mut count);}
          }
        }
      }
    }
    let mut dead=module(vec![block("entry",vec![inst("",Op::Return(Some(arg(Val::Int(0)))))]),block("dead.a",vec![inst("a",Op::Freeze(arg(local("b")))),inst("",Op::Return(Some(arg(local("a")))))]),block("dead.b",vec![inst("b",Op::Freeze(arg(local("a")))),inst("",Op::Return(Some(arg(local("b")))))]),],vec![]);
    audit(&dead,&mut count);blocks(&mut dead).swap(1,2);audit(&dead,&mut count);blocks(&mut dead)[1].instructions[0].op=Op::Freeze(arg(Val::Int(0)));audit(&dead,&mut count);
    let mut bad_phi=diamond();if let Op::Phi{incoming,..}=&mut blocks(&mut bad_phi)[3].instructions[0].op{incoming.pop();}audit(&bad_phi,&mut count);
    let mut collision=chain();let Item::Function(f)=&mut collision.items[0] else{panic!()};f.signature.params[0].name=Some("entry".into());audit(&collision,&mut count);
    println!("{{\"cases\":{},\"accepted\":{},\"rejected\":{},\"acceptance_and_diagnostic_mismatches\":0,\"invalid_candidate_schedules\":0,\"model_mutations\":0}}",count[0],count[1],count[2]);
}
